      ['name' => 'Garden District', 'blurb' => 'Historic mansions and tree-lined streets along the St. Charles streetcar.'],
      ['name' => 'Lower Garden District', 'blurb' => 'Close to downtown with Magazine Street shops and older apartments.'],
      ['name' => 'Marigny', 'blurb' => 'Creole cottages and Frenchmen Street music venues just downriver from the French Quarter.'],
      ['name' => 'Bywater', 'blurb' => 'An artsy neighborhood further downriver with colorful homes.'],
      ['name' => 'Mid-City', 'blurb' => 'A residential area near City Park on the Canal Street streetcar line.'],
      ['name' => 'Central Business District', 'blurb' => 'Converted buildings and newer apartments near the medical district and downtown offices.'],
